package in.tucor.api.auth; import jakarta.validation.constraints.*;
public final class AuthDtos {private AuthDtos(){} public record Register(@Email @NotBlank String email,@Size(min=8,max=72) String password,@NotNull Role role){} public record Login(@Email @NotBlank String email,@NotBlank String password,Boolean rememberMe){} public record Refresh(@NotBlank String refreshToken){} public record Tokens(String accessToken,String refreshToken,String tokenType,long expiresInSeconds,Role role,String email){} public record Me(String id,String email,Role role,String status,boolean emailVerified){}}